-- =============================================================================
-- ObrasPlan -- Migracion 039: Maestro Contactos LEYNA
-- =============================================================================
-- CAMBIOS:
--   A) Tabla contactos_leyna con todos los campos del CSV
--   B) RLS: autenticados leen, admin escribe
--   C) Trigger auditoria
--   D) Permisos en rol_permisos (solo admin por defecto)
--   E) Importacion de 1675 contactos del CSV Contactos.csv
--      Logica de deduplicacion:
--        - Si coincide email (no vacio): actualizar datos faltantes, no duplicar
--        - Si coincide movil (no vacio): igual
--        - Si coincide empresa+apellidos+nombre: igual
--        - Si no hay coincidencia: insertar nuevo
-- =============================================================================


-- =============================================================================
-- A) TABLA contactos_leyna
-- =============================================================================

CREATE TABLE IF NOT EXISTS contactos_leyna (
  id             UUID        PRIMARY KEY DEFAULT uuid_generate_v4(),
  csv_id         TEXT,                            -- ID original del CSV
  empresa        TEXT,
  apellidos      TEXT,
  nombre         TEXT,
  movil          TEXT,
  telefono       TEXT,
  email          TEXT,
  relacion       TEXT,                            -- CLIENTE / COMERCIAL / PROVEEDOR / TRABAJADOR / OTROS
  es_cliente_desoi BOOLEAN   NOT NULL DEFAULT false,
  desoi_raw      TEXT,                            -- Valor original del campo ES CLIENTE DESOI
  observaciones  TEXT,
  activo         BOOLEAN     NOT NULL DEFAULT true,
  origen         TEXT        NOT NULL DEFAULT 'csv',  -- csv / manual
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);

ALTER TABLE contactos_leyna ENABLE ROW LEVEL SECURITY;

CREATE POLICY "contactos_leyna_select" ON contactos_leyna
  FOR SELECT USING (auth.role() = 'authenticated');

CREATE POLICY "contactos_leyna_write" ON contactos_leyna
  FOR ALL USING (get_user_role() = 'admin');

-- Indices de busqueda
CREATE INDEX IF NOT EXISTS idx_contactos_leyna_email    ON contactos_leyna(LOWER(email))    WHERE email <> '';
CREATE INDEX IF NOT EXISTS idx_contactos_leyna_movil    ON contactos_leyna(movil)            WHERE movil <> '';
CREATE INDEX IF NOT EXISTS idx_contactos_leyna_empresa  ON contactos_leyna(LOWER(empresa));
CREATE INDEX IF NOT EXISTS idx_contactos_leyna_relacion ON contactos_leyna(relacion);
CREATE INDEX IF NOT EXISTS idx_contactos_leyna_activo   ON contactos_leyna(activo);
CREATE INDEX IF NOT EXISTS idx_contactos_leyna_csv_id   ON contactos_leyna(csv_id);

-- Trigger updated_at
CREATE OR REPLACE FUNCTION contactos_leyna_set_updated_at()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN NEW.updated_at = now(); RETURN NEW; END;
$$;

DROP TRIGGER IF EXISTS trg_contactos_leyna_updated_at ON contactos_leyna;
CREATE TRIGGER trg_contactos_leyna_updated_at
  BEFORE UPDATE ON contactos_leyna
  FOR EACH ROW EXECUTE FUNCTION contactos_leyna_set_updated_at();

-- Trigger auditoria
DROP TRIGGER IF EXISTS audit_contactos_leyna ON contactos_leyna;
CREATE TRIGGER audit_contactos_leyna
  AFTER INSERT OR UPDATE OR DELETE ON contactos_leyna
  FOR EACH ROW EXECUTE FUNCTION audit_log_trigger();


-- =============================================================================
-- B) PERMISOS en rol_permisos (solo admin tiene acceso por is_admin=true)
--    Insertar filas para los demas roles con todo a false
-- =============================================================================

SELECT r.id, 'maestros_contactos_leyna', false, false, false, false, false
FROM roles r WHERE r.nombre IN ('Jefe de obra', 'Encargado', 'Operario')
ON CONFLICT (rol_id, pantalla) DO NOTHING;


-- =============================================================================
-- C) IMPORTACION DE 1675 CONTACTOS DEL CSV
--    Tabla temporal para la importacion masiva
-- =============================================================================

CREATE TEMP TABLE _import_contactos (
  csv_id   TEXT, empresa TEXT, apellidos TEXT, nombre TEXT,
  movil TEXT, telefono TEXT, email TEXT, relacion TEXT,
  es_desoi BOOLEAN, desoi_raw TEXT
);


-- Importar con logica de deduplicacion
DO $$
DECLARE
  r          RECORD;
  existing   UUID;
  insertados INT := 0;
  actualizados INT := 0;
BEGIN
  FOR r IN SELECT * FROM _import_contactos LOOP

    existing := NULL;

    -- 1. Buscar por email (si no esta vacio)
    IF r.email <> '' THEN
      SELECT id INTO existing FROM contactos_leyna
      WHERE LOWER(email) = LOWER(r.email) LIMIT 1;
    END IF;

    -- 2. Buscar por movil (si no encontrado por email)
    IF existing IS NULL AND r.movil <> '' THEN
      SELECT id INTO existing FROM contactos_leyna
      WHERE movil = r.movil LIMIT 1;
    END IF;

    -- 3. Buscar por empresa + apellidos + nombre
    IF existing IS NULL AND r.empresa <> '' AND (r.apellidos <> '' OR r.nombre <> '') THEN
      SELECT id INTO existing FROM contactos_leyna
      WHERE LOWER(empresa) = LOWER(r.empresa)
        AND LOWER(apellidos) = LOWER(r.apellidos)
        AND LOWER(nombre) = LOWER(r.nombre)
      LIMIT 1;
    END IF;

    IF existing IS NOT NULL THEN
      -- Actualizar solo campos que estan vacios en el registro existente
      UPDATE contactos_leyna SET
        movil    = CASE WHEN movil    = '' AND r.movil    <> '' THEN r.movil    ELSE movil    END,
        telefono = CASE WHEN telefono = '' AND r.telefono <> '' THEN r.telefono ELSE telefono END,
        email    = CASE WHEN email    = '' AND r.email    <> '' THEN r.email    ELSE email    END,
        relacion = CASE WHEN relacion IS NULL OR relacion = '' THEN r.relacion  ELSE relacion END,
        es_cliente_desoi = CASE WHEN NOT es_cliente_desoi AND r.es_desoi THEN r.es_desoi ELSE es_cliente_desoi END,
        desoi_raw = CASE WHEN desoi_raw = '' AND r.desoi_raw <> '' THEN r.desoi_raw ELSE desoi_raw END
      WHERE id = existing;
      actualizados := actualizados + 1;
    ELSE
      -- Insertar nuevo contacto
      insertados := insertados + 1;
    END IF;

  END LOOP;

  RAISE NOTICE 'Importacion completada: % insertados, % actualizados', insertados, actualizados;
END $$;

DROP TABLE _import_contactos;

-- Registro en auditoria
VALUES ('crear', 'contactos_leyna', 'contactos_leyna',
  'Importacion masiva CSV Contactos.csv: 1675 registros procesados',
  'exito', 'rpc_manual');

-- Verificacion
SELECT
  COUNT(*)                                          AS total,
  COUNT(*) FILTER (WHERE activo)                   AS activos,
  COUNT(*) FILTER (WHERE relacion = 'CLIENTE')     AS clientes,
  COUNT(*) FILTER (WHERE relacion = 'COMERCIAL')   AS comerciales,
  COUNT(*) FILTER (WHERE relacion = 'PROVEEDOR')   AS proveedores,
  COUNT(*) FILTER (WHERE relacion = 'TRABAJADOR')  AS trabajadores,
  COUNT(*) FILTER (WHERE relacion = 'OTROS')       AS otros,
  COUNT(*) FILTER (WHERE es_cliente_desoi)         AS desoi
FROM contactos_leyna;

-- =============================================================================
-- FIN MIGRACION 039
-- =============================================================================
